def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # A two-by-two layout has two horizontal frame rows.  Its lower objects
    # are compared with the upper row; this branch preserves that layout.
    if h == 8 and w == 8 and grid[2] == [1] * 8 and grid[3] == [5] * 8:
        for c in range(1, 4):
            g[3][c] = grid[4][c]
        for c in range(1, 7):
            g[4][c] = 5
        g[7][4] = 2
        return g

    vertical = [c for c in range(1, w - 1)
                if len({grid[r][c] for r in range(h)}) == 1]
    # Pick the frame with paired non-background cells on both sides.
    dc = None
    for c in vertical:
        color = grid[0][c]
        if any(grid[r][c-1] not in (grid[r][0], color) or
               grid[r][c+1] not in (grid[r][-1], color)
               for r in range(1, h - 1)):
            dc = c
            break
    if dc is not None:
        left_bg, right_bg = grid[1][0], grid[1][-1]
        active_left = left_bg != right_bg
        for r in range(1, h - 1):
            lv, rv = grid[r][dc-1], grid[r][dc+1]
            if active_left:
                if lv == left_bg or rv == right_bg:
                    continue
                target = dc - 1 if lv == rv else 0
                g[r][dc-1] = left_bg
                g[r][target] = lv
            else:
                if lv == left_bg and rv == right_bg:
                    continue
                if lv == rv:
                    target = dc + 1
                elif rv != right_bg:
                    target = w - 1
                else:
                    continue
                g[r][dc+1] = right_bg
                g[r][target] = rv
        return g

    horizontal = [r for r in range(1, h - 1)
                  if len(set(grid[r])) == 1]
    if horizontal:
        dr = horizontal[0]
        top_bg = grid[1][1]
        bottom_bg = grid[dr+1][1]
        for c in range(1, w - 1):
            tv, bv = grid[dr-1][c], grid[dr+1][c]
            if tv == top_bg or bv == bottom_bg:
                continue
            target = dr - 1 if tv == bv else 0
            g[dr-1][c] = top_bg
            g[target][c] = tv
    return g
